#include "xxhash.h"
#include <string.h>

#define XXH_PRIME32_1 2654435761U
#define XXH_PRIME32_2 2246822519U
#define XXH_PRIME32_3 3266489917U
#define XXH_PRIME32_4  668265263U
#define XXH_PRIME32_5  374761393U

static uint32_t XXH_rotl32(uint32_t x, int r) { return (x << r) | (x >> (32 - r)); }

static uint32_t XXH_readLE32(const uint8_t* p) {
    uint32_t v;
    memcpy(&v, p, 4);
#if __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
    v = __builtin_bswap32(v);
#endif
    return v;
}

static uint32_t XXH32_round(uint32_t acc, uint32_t input) {
    acc += input * XXH_PRIME32_2;
    acc = XXH_rotl32(acc, 13);
    acc *= XXH_PRIME32_1;
    return acc;
}

static uint32_t XXH32_avalanche(uint32_t h) {
    h ^= h >> 15;
    h *= XXH_PRIME32_2;
    h ^= h >> 13;
    h *= XXH_PRIME32_3;
    h ^= h >> 16;
    return h;
}

static uint32_t XXH32_finalize(uint32_t h, const uint8_t* p, size_t len) {
    len &= 15;
    while (len >= 4) {
        h += XXH_readLE32(p) * XXH_PRIME32_3;
        p += 4;
        h = XXH_rotl32(h, 17) * XXH_PRIME32_4;
        len -= 4;
    }
    while (len > 0) {
        h += (*p) * XXH_PRIME32_5;
        p++;
        h = XXH_rotl32(h, 11) * XXH_PRIME32_1;
        len--;
    }
    return XXH32_avalanche(h);
}

uint32_t XXH32(const void* input, size_t len, uint32_t seed) {
    const uint8_t* p = (const uint8_t*)input;
    const uint8_t* const end = p + len;
    uint32_t h;
    if (len >= 16) {
        const uint8_t* const limit = end - 16;
        uint32_t v1 = seed + XXH_PRIME32_1 + XXH_PRIME32_2;
        uint32_t v2 = seed + XXH_PRIME32_2;
        uint32_t v3 = seed + 0;
        uint32_t v4 = seed - XXH_PRIME32_1;
        do {
            v1 = XXH32_round(v1, XXH_readLE32(p)); p += 4;
            v2 = XXH32_round(v2, XXH_readLE32(p)); p += 4;
            v3 = XXH32_round(v3, XXH_readLE32(p)); p += 4;
            v4 = XXH32_round(v4, XXH_readLE32(p)); p += 4;
        } while (p <= limit);
        h = XXH_rotl32(v1, 1) + XXH_rotl32(v2, 7) + XXH_rotl32(v3, 12) + XXH_rotl32(v4, 18);
    } else {
        h = seed + XXH_PRIME32_5;
    }
    h += (uint32_t)len;
    return XXH32_finalize(h, p, len);
}

void XXH32_reset(XXH32_state_t* st, uint32_t seed) {
    st->total = 0;
    st->v1 = seed + XXH_PRIME32_1 + XXH_PRIME32_2;
    st->v2 = seed + XXH_PRIME32_2;
    st->v3 = seed + 0;
    st->v4 = seed - XXH_PRIME32_1;
    st->memsize = 0;
}

void XXH32_update(XXH32_state_t* st, const void* input, size_t len) {
    const uint8_t* p = (const uint8_t*)input;
    const uint8_t* const end = p + len;
    st->total += (uint32_t)len;

    if (st->memsize + len < 16) {
        memcpy(st->mem + st->memsize, p, len);
        st->memsize += len;
        return;
    }
    if (st->memsize) {
        size_t fill = 16 - st->memsize;
        memcpy(st->mem + st->memsize, p, fill);
        st->v1 = XXH32_round(st->v1, XXH_readLE32(st->mem + 0));
        st->v2 = XXH32_round(st->v2, XXH_readLE32(st->mem + 4));
        st->v3 = XXH32_round(st->v3, XXH_readLE32(st->mem + 8));
        st->v4 = XXH32_round(st->v4, XXH_readLE32(st->mem + 12));
        p += fill;
        st->memsize = 0;
    }
    if (p <= end - 16) {
        const uint8_t* const limit = end - 16;
        uint32_t v1 = st->v1, v2 = st->v2, v3 = st->v3, v4 = st->v4;
        do {
            v1 = XXH32_round(v1, XXH_readLE32(p)); p += 4;
            v2 = XXH32_round(v2, XXH_readLE32(p)); p += 4;
            v3 = XXH32_round(v3, XXH_readLE32(p)); p += 4;
            v4 = XXH32_round(v4, XXH_readLE32(p)); p += 4;
        } while (p <= limit);
        st->v1 = v1; st->v2 = v2; st->v3 = v3; st->v4 = v4;
    }
    if (p < end) {
        memcpy(st->mem, p, (size_t)(end - p));
        st->memsize = (size_t)(end - p);
    }
}

uint32_t XXH32_digest(const XXH32_state_t* st) {
    uint32_t h;
    if (st->total >= 16) {
        h = XXH_rotl32(st->v1, 1) + XXH_rotl32(st->v2, 7) +
            XXH_rotl32(st->v3, 12) + XXH_rotl32(st->v4, 18);
    } else {
        h = st->v3 /* == seed */ + XXH_PRIME32_5;
    }
    h += st->total;
    return XXH32_finalize(h, st->mem, st->total);
}

