#include "lz4block.h"
#include <string.h>
#include <stdint.h>
#include <assert.h>

#define MINMATCH 4
#define WILDCOPYLENGTH 8
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_minLength (MFLIMIT+1)
#define LZ4_64Klimit (65536 + MFLIMIT - 1)
#define LZ4_skipTrigger 6
#define LZ4_DISTANCE_MAX 65535

#define ML_BITS 4
#define ML_MASK ((1U<<ML_BITS)-1)
#define RUN_BITS (8-ML_BITS)
#define RUN_MASK ((1U<<RUN_BITS)-1)

#define LZ4_HASHLOG 12
#define LZ4_HASHTABLESIZE (1 << LZ4_HASHLOG)

#define KB *(1<<10)
#define MB *(1<<20)

static uint32_t LZ4_read32(const void* p) { uint32_t v; memcpy(&v, p, 4); return v; }
static uint64_t LZ4_read64(const void* p) { uint64_t v; memcpy(&v, p, 8); return v; }
static void LZ4_write16(void* p, uint16_t v) { memcpy(p, &v, 2); }
static void LZ4_write32(void* p, uint32_t v) { memcpy(p, &v, 4); }
static void LZ4_writeLE16(void* p, uint16_t v) {
#if __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
    v = (uint16_t)((v >> 8) | (v << 8));
#endif
    memcpy(p, &v, 2);
}
static void LZ4_writeLE32(void* p, uint32_t v) {
#if __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
    v = __builtin_bswap32(v);
#endif
    memcpy(p, &v, 4);
}
static uint64_t LZ4_read_ARCH(const void* p) { return LZ4_read64(p); }

/* ---------- hashing ---------- */
#define LZ4_PRIME5 889523592379ULL

static unsigned LZ4_hash4(uint32_t v, int hashLog) {
    return (v * 2654435761U) >> (MINMATCH*8 - hashLog);
}
static unsigned LZ4_hash5(uint64_t v, int hashLog) {
    return (unsigned)(((v << 24) * LZ4_PRIME5) >> (64 - hashLog));
}
static unsigned LZ4_hashPosition(const void* p, tableType_t tableType) {
    if (tableType == byU16)
        return LZ4_hash4(LZ4_read32(p), LZ4_HASHLOG);
    return LZ4_hash5(LZ4_read_ARCH(p), LZ4_HASHLOG);
}

static void LZ4_putIndexOnHash(uint32_t idx, unsigned h, void* tableBase, tableType_t tableType) {
    switch (tableType) {
    case byU16: { uint16_t* t = (uint16_t*)tableBase; t[h] = (uint16_t)idx; return; }
    case byU32: { uint32_t* t = (uint32_t*)tableBase; t[h] = idx; return; }
    case byPtr: break;
    }
}
static uint32_t LZ4_getIndexOnHash(unsigned h, const void* tableBase, tableType_t tableType) {
    switch (tableType) {
    case byU16: { const uint16_t* t = (const uint16_t*)tableBase; return t[h]; }
    case byU32: { const uint32_t* t = (const uint32_t*)tableBase; return t[h]; }
    case byPtr: break;
    }
    return 0;
}

static void LZ4_putPosition(const uint8_t* ip, void* tableBase, tableType_t tableType, const uint8_t* srcBase) {
    unsigned h = LZ4_hashPosition(ip, tableType);
    LZ4_putIndexOnHash((uint32_t)(ip - srcBase), h, tableBase, tableType);
}

/* wild copy of 8-byte chunks */
static void LZ4_wildCopy8(void* dst, const void* src, void* dstEnd) {
    uint8_t* d = (uint8_t*)dst;
    const uint8_t* s = (const uint8_t*)src;
    uint8_t* const e = (uint8_t*)dstEnd;
    do { memcpy(d, s, 8); d += 8; s += 8; } while (d < e);
}

/* count common bytes (little-endian assumption for NbCommonBytes) */
static unsigned LZ4_NbCommonBytes(uint64_t val) {
#if defined(__GNUC__)
    return (unsigned)(__builtin_ctzll(val) >> 3);
#else
    unsigned n = 0;
    while ((val & 0xff) == 0) { val >>= 8; n++; }
    return n;
#endif
}

static unsigned LZ4_count(const uint8_t* pIn, const uint8_t* pMatch, const uint8_t* pInLimit) {
    const uint8_t* const pStart = pIn;

    while (pIn < pInLimit - 7) {
        uint64_t diff = LZ4_read_ARCH(pMatch) ^ LZ4_read_ARCH(pIn);
        if (!diff) { pIn += 8; pMatch += 8; continue; }
        return (unsigned)(pIn - pStart) + LZ4_NbCommonBytes(diff);
    }
    if ((pIn < pInLimit - 3) && (LZ4_read32(pMatch) == LZ4_read32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < pInLimit - 1) && (*(const uint16_t*)pMatch == *(const uint16_t*)pIn)) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

/* ============ stream state ============ */

void LZ4_resetStream(LZ4_stream_t* st) {
    memset(st, 0, sizeof(*st));
}

/* prepare table: emulate LZ4_prepareTable for our use:
   make existing table content not reference-able as prefix */
static void LZ4_prepareTable(LZ4_stream_t* st, int inputSize, tableType_t tableType) {
    /* If the table hasn't been used, no need to do anything (dirty check). */
    if (st->tableType != (int)tableType || st->dirty) {
        memset(st->hashTable, 0, sizeof(st->hashTable));
        st->currentOffset = 0;
        st->tableType = (int)tableType;
        st->dirty = 0;
        st->dictSize = 0;
        st->base = NULL;
        st->dictEnd = NULL;
        return;
    }
    /* table may contain data: shift offsets so old entries become "external dict" with size 0 */
    if (st->dictEnd != NULL) {
        /* existing data in table: mark as external dictionary of size 0 handled by caller */
    }
    (void)inputSize;
}

void LZ4_resetStream_fast(LZ4_stream_t* st) {
    /* Equivalent to reference: LZ4_prepareTable(ctx, 0, byU32) with dirty flag semantics.
       For us: if table was never used, nothing needed; otherwise invalidate by rebasing. */
    if (!st->dirty) return; /* nothing in table */
    /* Move base forward so that all entries are below the new startIndex (invalid) */
    st->base = st->dictEnd; /* prefix becomes zero-sized at end of previous block */
    /* entries older than currentOffset-65535 considered invalid via distance check */
}

/* ============ fast compression ============ */

typedef enum { noDict = 0, withPrefix64k, usingExtDict, usingDictCtx } dict_directive;
typedef enum { noDictIssue = 0, dictSmall } dictIssue_directive;
typedef enum { notLimited = 0, limitedOutput = 1, fillOutput = 2 } limitedOutput_directive;

static int LZ4_compress_generic(
                 LZ4_stream_t* const cctx,
                 const char* const source,
                 char* const dest,
                 const int inputSize,
                 char* const maxInputSize_unused,
                 const int maxOutputSize,
                 const limitedOutput_directive outputDirective,
                 const tableType_t tableType,
                 const dict_directive dictDirective,
                 const dictIssue_directive dictIssue,
                 const int acceleration)
{
    const uint8_t* ip = (const uint8_t*)source;
    uint8_t* op = (uint8_t*)dest;
    uint8_t* const olimit = op + maxOutputSize;

    const uint8_t* base;
    const uint8_t* lowLimit;
    const uint8_t* lowRefLimit = ip - cctx->dictSize;
    const uint8_t* const dictionary = cctx->dictionary;
    const uint8_t* const dictEnd = dictionary + cctx->dictSize;
    const uint32_t startIndex = cctx->currentOffset;
    uint32_t* const hashTable = cctx->hashTable;
    const uint8_t* anchor;
    const uint8_t* const iend = ip + inputSize;
    const uint8_t* const mflimitPlusOne = iend - MFLIMIT + 1;
    const uint8_t* const matchlimit = iend - LASTLITERALS;
    uint32_t forwardH;

    (void)maxInputSize_unused;

    /* init conditions */
    if ((uint32_t)inputSize > 0x7E000000) return 0; /* LZ4_MAX_INPUT_SIZE */
    if ((tableType == byU16) && (inputSize >= LZ4_64Klimit)) return 0;
    if (inputSize < LZ4_minLength) goto _last_literals;

    /* First Byte */
    base = (const uint8_t*)source - startIndex;
    if (dictDirective == usingExtDict) {
        lowLimit = dictionary;
    } else {
        lowLimit = (const uint8_t*)source;
    }
    anchor = ip;
    LZ4_putPosition(ip, hashTable, tableType, base);
    ip++;
    forwardH = LZ4_hashPosition(ip, tableType);

    /* Main Loop */
    for ( ; ; ) {
        const uint8_t* match;
        uint8_t* token;
        const uint8_t* filledIp;

        /* Find a match */
        {
            const uint8_t* forwardIp = ip;
            unsigned step = 1;
            unsigned searchMatchNb = (unsigned)acceleration << LZ4_skipTrigger;
            do {
                unsigned const h = forwardH;
                uint32_t const current = (uint32_t)(forwardIp - base);
                uint32_t matchIndex = LZ4_getIndexOnHash(h, hashTable, tableType);
                ip = forwardIp;
                forwardIp += step;
                step = (searchMatchNb++ >> LZ4_skipTrigger);

                if (forwardIp > mflimitPlusOne) goto _last_literals;

                if (dictDirective == usingDictCtx) {
                    /* not used by CLI fast path */
                } else if (dictDirective == usingExtDict) {
                    if (matchIndex < startIndex) {
                        match = dictEnd - (startIndex - matchIndex);
                        lowLimit = dictionary;
                    } else {
                        match = base + matchIndex;
                        lowLimit = (const uint8_t*)source;
                    }
                } else { /* single continuous memory segment */
                    match = base + matchIndex;
                }
                forwardH = LZ4_hashPosition(forwardIp, tableType);
                LZ4_putIndexOnHash(current, h, hashTable, tableType);

                if ((dictIssue == dictSmall) && (matchIndex < startIndex /* prefixIdx */)) continue;
                if ((tableType != byU16) && (matchIndex + LZ4_DISTANCE_MAX < current)) continue;
                if (LZ4_read32(match) != LZ4_read32(ip)) continue;
                break;
            } while (1);
        }

        /* Catch up */
        filledIp = ip;
        while (((ip > anchor) && (match > lowLimit)) && (ip[-1] == match[-1])) { ip--; match--; }

        /* Encode Literals */
        {
            unsigned const litLength = (unsigned)(ip - anchor);
            token = op++;
            if ((outputDirective == limitedOutput) &&
                (op + litLength + (2 + 1 + LASTLITERALS) + (litLength/255) > olimit)) {
                return 0;
            }
            if (litLength >= RUN_MASK) {
                int len = (int)(litLength - RUN_MASK);
                *token = (uint8_t)(RUN_MASK << ML_BITS);
                for (; len >= 255; len -= 255) *op++ = 255;
                *op++ = (uint8_t)len;
            } else {
                *token = (uint8_t)(litLength << ML_BITS);
            }
            /* Copy Literals */
            LZ4_wildCopy8(op, anchor, op + litLength);
            op += litLength;
        }

_next_match:
        /* Encode Offset */
        LZ4_writeLE16(op, (uint16_t)(ip - match)); op += 2;

        /* Encode MatchLength */
        {
            unsigned matchCode;

            if ((dictDirective == usingExtDict) && (lowLimit == dictionary)) {
                const uint8_t* limit = ip + (dictEnd - match);
                if (limit > matchlimit) limit = matchlimit;
                matchCode = LZ4_count(ip + MINMATCH, limit, matchlimit);
                ip += (size_t)matchCode + MINMATCH;
                if (ip == limit) {
                    unsigned const more = LZ4_count(limit, (const uint8_t*)source, matchlimit);
                    matchCode += more;
                    ip += more;
                }
            } else {
                matchCode = LZ4_count(ip + MINMATCH, match + MINMATCH, matchlimit);
                ip += (size_t)matchCode + MINMATCH;
            }

            if ((outputDirective == limitedOutput) &&
                (op + (1 + LASTLITERALS) + (matchCode + 240)/255 > olimit)) {
                return 0;
            }

            if (matchCode >= ML_MASK) {
                *token = (uint8_t)(*token + ML_MASK);
                matchCode -= ML_MASK;
                LZ4_write32(op, 0xFFFFFFFF);
                while (matchCode >= 4*255) {
                    op += 4;
                    LZ4_write32(op, 0xFFFFFFFF);
                    matchCode -= 4*255;
                }
                op += matchCode / 255;
                *op++ = (uint8_t)(matchCode % 255);
            } else {
                *token = (uint8_t)(*token + matchCode);
            }
        }

        anchor = ip;

        /* Test end of chunk */
        if (ip >= mflimitPlusOne) break;

        /* Fill table */
        LZ4_putPosition(ip - 2, hashTable, tableType, base);

        /* Test next position */
        {
            unsigned const h = LZ4_hashPosition(ip, tableType);
            uint32_t const current = (uint32_t)(ip - base);
            uint32_t matchIndex = LZ4_getIndexOnHash(h, hashTable, tableType);
            if (dictDirective == usingExtDict) {
                if (matchIndex < startIndex) {
                    match = dictEnd - (startIndex - matchIndex);
                    lowLimit = dictionary;
                } else {
                    match = base + matchIndex;
                    lowLimit = (const uint8_t*)source;
                }
            } else {
                match = base + matchIndex;
            }
            LZ4_putIndexOnHash(current, h, hashTable, tableType);
            if ((dictIssue == dictSmall) && (matchIndex < startIndex)) goto _next_match_no;
            if ((tableType != byU16) && (matchIndex + LZ4_DISTANCE_MAX < current)) goto _next_match_no;
            if (LZ4_read32(match) == LZ4_read32(ip)) {
                token = op++;
                *token = 0;
                goto _next_match;
            }
        }
_next_match_no:;

        /* Prepare next loop */
        forwardH = LZ4_hashPosition(++ip, tableType);
    }

_last_literals:
    /* Encode Last Literals */
    {
        size_t lastRun = (size_t)(iend - anchor);
        if ((outputDirective == limitedOutput) &&
            (op + lastRun + 1 + ((lastRun + 255 - RUN_MASK) / 255) > olimit)) {
            return 0;
        }
        if (lastRun >= RUN_MASK) {
            size_t accumulator = lastRun - RUN_MASK;
            *op++ = (uint8_t)(RUN_MASK << ML_BITS);
            for (; accumulator >= 255; accumulator -= 255) *op++ = 255;
            *op++ = (uint8_t)accumulator;
        } else {
            *op++ = (uint8_t)(lastRun << ML_BITS);
        }
        memcpy(op, anchor, lastRun);
        op += lastRun;
    }

    return (int)((char*)op - dest);
}

/* public one-shot compression */
int LZ4_compress_fast(const char* src, char* dst, int srcSize, int dstCapacity, int acceleration) {
    LZ4_stream_t ctx;
    tableType_t const tableType = (srcSize < LZ4_64Klimit) ? byU16 : byU32;
    if (acceleration < 1) acceleration = 1;
    if (srcSize == 0) {
        /* empty input still produces an end token */
    }
    LZ4_resetStream(&ctx);
    ctx.tableType = (int)tableType;
    return LZ4_compress_generic(&ctx, src, dst, srcSize, NULL, dstCapacity,
                                limitedOutput, tableType, noDict, noDictIssue, acceleration);
}

/* continue compression over stream; mimics LZ4_compress_fast_continue semantics */
int LZ4_compress_fast_continue(LZ4_stream_t* st, const char* src, char* dst, int srcSize, int dstCapacity, int acceleration) {
    const uint8_t* const source = (const uint8_t*)src;
    tableType_t const tableType = byU32;
    dict_directive dictDirective;
    const uint8_t* prefixEnd;

    if (acceleration < 1) acceleration = 1;

    if (st->dirty) {
        /* First block of a stream; or re-init: behave like fresh */
    }

    prefixEnd = st->dictEnd;

    if ((st->dictSize == 0) && (st->dictEnd == NULL || prefixEnd == source) && !st->dirty) {
        /* brand new stream, contiguous start */
    }

    if (prefixEnd == source && st->dictEnd != NULL) {
        /* contiguous with previous block */
        dictDirective = noDict; /* prefix mode: window includes previous data */
        /* base/currentOffset already set so that previous block is addressable */
    } else if (st->dictEnd != NULL && st->dictSize > 0) {
        /* external dictionary */
        dictDirective = usingExtDict;
    } else {
        dictDirective = noDict;
    }

    {
        int result;
        /* renormalize check for huge streams omitted (offsets < 2GB in our use) */
        result = LZ4_compress_generic(st, src, dst, srcSize, NULL, dstCapacity,
                                      limitedOutput, tableType, dictDirective, noDictIssue, acceleration);
        /* update stream state */
        st->dirty = 1;
        st->tableType = (int)byU32;
        if (dictDirective == usingExtDict) {
            /* dictionary stays external; new data appended after dictEnd? Caller manages buffers.
               We treat the just-compressed block as new external dict segment. */
            st->dictionary = source;
            st->dictSize = (uint32_t)srcSize;
            st->currentOffset = (uint32_t)srcSize;
            st->base = source - srcSize;
            st->dictEnd = source + srcSize;
        } else {
            if (st->dictEnd == NULL) {
                st->currentOffset = 0;
                st->base = source;
            }
            st->currentOffset += (uint32_t)srcSize;
            st->base = source - st->currentOffset;
            st->dictEnd = source + srcSize;
            st->dictionary = source;
            st->dictSize = (uint32_t)(st->dictEnd - source); /* prefix size */
        }
        return result;
    }
}

/* ============ decompression ============ */

int LZ4_decompress_safe(const char* source, char* dest, int compressedSize, int maxDecompressedSize) {
    const uint8_t* ip = (const uint8_t*)source;
    const uint8_t* const iend = ip + compressedSize;
    uint8_t* op = (uint8_t*)dest;
    uint8_t* const oend = op + maxDecompressedSize;

    while (1) {
        unsigned token;
        size_t length;
        const uint8_t* match;
        size_t offset;

        token = *ip++;

        /* literals */
        length = token >> ML_BITS;
        if (length == RUN_MASK) {
            unsigned s;
            do {
                if (ip >= iend) return (int)-(ip - (const uint8_t*)source - 1);
                s = *ip++;
                length += s;
            } while (s == 255);
        }
        if ((op + length > oend) || (ip + length > iend)) {
            /* allow exact end */
            if (op + length > oend || ip + length > iend) return (int)-(ip - (const uint8_t*)source - 1);
        }
        memcpy(op, ip, length);
        op += length;
        ip += length;

        if (ip >= iend) break; /* end of block: last sequence has literals only */

        /* offset */
        offset = (size_t)ip[0] | ((size_t)ip[1] << 8);
        ip += 2;
        if (offset == 0 || offset > (size_t)(op - (uint8_t*)dest)) return (int)-(ip - (const uint8_t*)source - 1);
        match = op - offset;

        /* match length */
        length = token & ML_MASK;
        if (length == ML_MASK) {
            unsigned s;
            do {
                if (ip >= iend) return (int)-(ip - (const uint8_t*)source - 1);
                s = *ip++;
                length += s;
            } while (s == 255);
        }
        length += MINMATCH;

        if (op + length > oend) return (int)-(ip - (const uint8_t*)source - 1);

        /* copy match */
        if (offset >= 8) {
            LZ4_wildCopy8(op, match, op + length);
            op += length;
        } else {
            /* overlapping / short offset copy */
            uint8_t* ope = op + length;
            if (offset == 1) {
                uint8_t v = *match;
                memset(op, v, length);
                op = ope;
            } else {
                while (op < ope) { *op = *match; op++; match++; }
            }
        }
    }
    return (int)(op - (uint8_t*)dest);
}

