#include "lz4block.h"
#include <string.h>
#include <stdint.h>
#include <assert.h>

#define MINMATCH 4
#define WILDCOPYLENGTH 8
#define LASTLITERALS 5
#define MFLIMIT 12
#define LZ4_minLength (MFLIMIT+1)
#define LZ4_64Klimit (65536 + MFLIMIT - 1)
#define LZ4_skipTrigger 6
#define LZ4_DISTANCE_MAX 65535

#define ML_BITS 4
#define ML_MASK ((1U<<ML_BITS)-1)
#define RUN_BITS (8-ML_BITS)
#define RUN_MASK ((1U<<RUN_BITS)-1)

#define LZ4_HASHLOG 12
#define LZ4_HASHTABLESIZE (1 << LZ4_HASHLOG)

#define KB *(1<<10)
#define MB *(1<<20)

static uint32_t LZ4_read32(const void* p) { uint32_t v; memcpy(&v, p, 4); return v; }
static uint64_t LZ4_read64(const void* p) { uint64_t v; memcpy(&v, p, 8); return v; }
static void LZ4_write16(void* p, uint16_t v) { memcpy(p, &v, 2); }
static void LZ4_write32(void* p, uint32_t v) { memcpy(p, &v, 4); }
static void LZ4_writeLE16(void* p, uint16_t v) {
#if __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
    v = (uint16_t)((v >> 8) | (v << 8));
#endif
    memcpy(p, &v, 2);
}
static void LZ4_writeLE32(void* p, uint32_t v) {
#if __BYTE_ORDER__ == __ORDER_BIG_ENDIAN__
    v = __builtin_bswap32(v);
#endif
    memcpy(p, &v, 4);
}
static uint64_t LZ4_read_ARCH(const void* p) { return LZ4_read64(p); }

/* ---------- hashing ---------- */
#define LZ4_PRIME5 889523592379ULL

static unsigned LZ4_hash4(uint32_t v, int hashLog) {
    return (v * 2654435761U) >> (MINMATCH*8 - hashLog);
}
static unsigned LZ4_hash5(uint64_t v, int hashLog) {
    return (unsigned)(((v << 24) * LZ4_PRIME5) >> (64 - hashLog));
}
static unsigned LZ4_hashPosition(const void* p, tableType_t tableType) {
    if (tableType == byU16)
        return LZ4_hash4(LZ4_read32(p), LZ4_HASHLOG);
    return LZ4_hash5(LZ4_read_ARCH(p), LZ4_HASHLOG);
}

static void LZ4_putIndexOnHash(uint32_t idx, unsigned h, void* tableBase, tableType_t tableType) {
    switch (tableType) {
    case byU16: { uint16_t* t = (uint16_t*)tableBase; t[h] = (uint16_t)idx; return; }
    case byU32: { uint32_t* t = (uint32_t*)tableBase; t[h] = idx; return; }
    case byPtr: break;
    }
}
static uint32_t LZ4_getIndexOnHash(unsigned h, const void* tableBase, tableType_t tableType) {
    switch (tableType) {
    case byU16: { const uint16_t* t = (const uint16_t*)tableBase; return t[h]; }
    case byU32: { const uint32_t* t = (const uint32_t*)tableBase; return t[h]; }
    case byPtr: break;
    }
    return 0;
}

static void LZ4_putPosition(const uint8_t* ip, void* tableBase, tableType_t tableType, const uint8_t* srcBase) {
    unsigned h = LZ4_hashPosition(ip, tableType);
    LZ4_putIndexOnHash((uint32_t)(ip - srcBase), h, tableBase, tableType);
}

/* wild copy of 8-byte chunks */
static void LZ4_wildCopy8(void* dst, const void* src, void* dstEnd) {
    uint8_t* d = (uint8_t*)dst;
    const uint8_t* s = (const uint8_t*)src;
    uint8_t* const e = (uint8_t*)dstEnd;
    do { memcpy(d, s, 8); d += 8; s += 8; } while (d < e);
}

/* count common bytes (little-endian assumption for NbCommonBytes) */
static unsigned LZ4_NbCommonBytes(uint64_t val) {
#if defined(__GNUC__)
    return (unsigned)(__builtin_ctzll(val) >> 3);
#else
    unsigned n = 0;
    while ((val & 0xff) == 0) { val >>= 8; n++; }
    return n;
#endif
}

static unsigned LZ4_count(const uint8_t* pIn, const uint8_t* pMatch, const uint8_t* pInLimit) {
    const uint8_t* const pStart = pIn;

    while (pIn < pInLimit - 7) {
        uint64_t diff = LZ4_read_ARCH(pMatch) ^ LZ4_read_ARCH(pIn);
        if (!diff) { pIn += 8; pMatch += 8; continue; }
        return (unsigned)(pIn - pStart) + LZ4_NbCommonBytes(diff);
    }
    if ((pIn < pInLimit - 3) && (LZ4_read32(pMatch) == LZ4_read32(pIn))) { pIn += 4; pMatch += 4; }
    if ((pIn < pInLimit - 1) && (*(const uint16_t*)pMatch == *(const uint16_t*)pIn)) { pIn += 2; pMatch += 2; }
    if ((pIn < pInLimit) && (*pMatch == *pIn)) pIn++;
    return (unsigned)(pIn - pStart);
}

/* ============ stream state ============ */

void LZ4_resetStream(LZ4_stream_t* st) {
    memset(st, 0, sizeof(*st));
}

/* prepare table: emulate LZ4_prepareTable for our use:
   make existing table content not reference-able as prefix */
static void LZ4_prepareTable(LZ4_stream_t* st, int inputSize, tableType_t tableType) {
    /* If the table hasn't been used, no need to do anything (dirty check). */
    if (st->tableType != (int)tableType || st->dirty) {
        memset(st->hashTable, 0, sizeof(st->hashTable));
        st->currentOffset = 0;
        st->tableType = (int)tableType;
        st->dirty = 0;
        st->dictSize = 0;
        st->base = NULL;
        st->dictEnd = NULL;
        return;
    }
    /* table may contain data: shift offsets so old entries become "external dict" with size 0 */
    if (st->dictEnd != NULL) {
        /* existing data in table: mark as external dictionary of size 0 handled by caller */
    }
    (void)inputSize;
}

void LZ4_resetStream_fast(LZ4_stream_t* st) {
    /* Equivalent to reference: LZ4_prepareTable(ctx, 0, byU32) with dirty flag semantics.
       For us: if table was never used, nothing needed; otherwise invalidate by rebasing. */
    if (!st->dirty) return; /* nothing in table */
    /* Move base forward so that all entries are below the new startIndex (invalid) */
    st->base = st->dictEnd; /* prefix becomes zero-sized at end of previous block */
    /* entries older than currentOffset-65535 considered invalid via distance check */
}

/* ============ fast compression ============ */

typedef enum { noDict = 0, withPrefix64k, usingExtDict, usingDictCtx } dict_directive;
typedef enum { noDictIssue = 0, dictSmall } dictIssue_directive;
typedef enum { notLimited = 0, limitedOutput = 1, fillOutput = 2 } limitedOutput_directive;

static int LZ4_compress_generic(
                 LZ4_stream_t* const cctx,
                 const char* const source,
                 char* const dest,
                 const int inputSize,
                 char* const maxInputSize_unused,
                 const int maxOutputSize,
                 const limitedOutput_directive outputDirective,
                 const tableType_t tableType,
                 const dict_directive dictDirective,
                 const dictIssue_directive dictIssue,
                 const int acceleration)
{
    const uint8_t* ip = (const uint8_t*)source;
    uint8_t* op = (uint8_t*)dest;
    uint8_t* const olimit = op + maxOutputSize;

    const uint8_t* base;
    const uint8_t* lowLimit;
    const uint8_t* lowRefLimit = ip - cctx->dictSize;
    const uint8_t* const dictionary = cctx->dictionary;
    const uint8_t* const dictEnd = dictionary + cctx->dictSize;
    const uint32_t startIndex = cctx->currentOffset;
    uint32_t* const hashTable = cctx->hashTable;
