            unsigned matchCode;

            if ((dictDirective == usingExtDict) && (lowLimit == dictionary)) {
                const uint8_t* limit = ip + (dictEnd - match);
                if (limit > matchlimit) limit = matchlimit;
                matchCode = LZ4_count(ip + MINMATCH, limit, matchlimit);
                ip += (size_t)matchCode + MINMATCH;
                if (ip == limit) {
                    unsigned const more = LZ4_count(limit, (const uint8_t*)source, matchlimit);
                    matchCode += more;
                    ip += more;
                }
            } else {
                matchCode = LZ4_count(ip + MINMATCH, match + MINMATCH, matchlimit);
                ip += (size_t)matchCode + MINMATCH;
            }

            if ((outputDirective == limitedOutput) &&
                (op + (1 + LASTLITERALS) + (matchCode + 240)/255 > olimit)) {
                return 0;
            }

            if (matchCode >= ML_MASK) {
                *token = (uint8_t)(*token + ML_MASK);
                matchCode -= ML_MASK;
                LZ4_write32(op, 0xFFFFFFFF);
                while (matchCode >= 4*255) {
                    op += 4;
                    LZ4_write32(op, 0xFFFFFFFF);
                    matchCode -= 4*255;
                }
                op += matchCode / 255;
                *op++ = (uint8_t)(matchCode % 255);
            } else {
                *token = (uint8_t)(*token + matchCode);
            }
        }

        anchor = ip;

        /* Test end of chunk */
        if (ip >= mflimitPlusOne) break;

        /* Fill table */
        LZ4_putPosition(ip - 2, hashTable, tableType, base);

        /* Test next position */
        {
            unsigned const h = LZ4_hashPosition(ip, tableType);
            uint32_t const current = (uint32_t)(ip - base);
            uint32_t matchIndex = LZ4_getIndexOnHash(h, hashTable, tableType);
            if (dictDirective == usingExtDict) {
                if (matchIndex < startIndex) {
                    match = dictEnd - (startIndex - matchIndex);
                    lowLimit = dictionary;
                } else {
