/* Block-level differential tester:
   usage: blktest c <infile> <outfile>   -> compress whole file as ONE block (fast, accel 1)
          blktest d <infile> <outfile> <origSize> -> decompress block
*/
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "lz4block.h"

int main(int argc, char** argv) {
    if (argc < 4) return 2;
    FILE* f = fopen(argv[2], "rb");
    if (!f) { perror("open"); return 2; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char* in = malloc(sz ? sz : 1);
    fread(in, 1, sz, f);
    fclose(f);

    if (argv[1][0] == 'c') {
        int cap = (int)sz + sz/255 + 64;
        char* out = malloc(cap);
        int r = LZ4_compress_fast(in, out, (int)sz, cap, 1);
        FILE* o = fopen(argv[3], "wb");
        fwrite(out, 1, r, o);
        fclose(o);
        fprintf(stderr, "csize=%d\n", r);
    } else {
        long osz = atol(argv[4]);
        char* out = malloc(osz ? osz : 1);
        int r = LZ4_decompress_safe(in, out, (int)sz, (int)osz);
        if (r < 0) { fprintf(stderr, "decode error %d\n", r); return 1; }
        FILE* o = fopen(argv[3], "wb");
        fwrite(out, 1, r, o);
        fclose(o);
    }
    return 0;
}

