def gen_struct(rng, n):
    # random text with repeats
    words=[bytes([rng.getrandbits(8) for _ in range(rng.randint(2,9))]) for _ in range(rng.randint(2,30))]
    out=bytearray()
    while len(out)<n:
        out+=rng.choice(words)
        if rng.random()<0.3: out+=b' '
    return bytes(out[:n])
def gen_period(rng, n):
    p=rng.randint(1,20); base=bytes(rng.getrandbits(8) for _ in range(p))
    return (base*(n//p+1))[:n]
def gen_runs(rng, n):
    out=bytearray()
    while len(out)<n:
        out+=bytes([rng.getrandbits(8)])*rng.randint(1,50)
